-- MEFG.TECH · Carga de 340 juegos de PS4
-- Pegar TODO este archivo en Supabase → SQL Editor → New query → Run.
-- 1) Borra los 10 juegos de PS4 de ejemplo.
-- 2) Carga los juegos nuevos OCULTOS (active = false), con precios de referencia.
--    Revisalos en el panel → Inventario, ajustá precios y mostralos.
-- Se puede volver a ejecutar: no duplica juegos que ya existan con el mismo nombre.
-- =====================================================================

delete from public.products
where plat = 'PS4' and id in (15, 19, 26, 27, 31, 32, 39, 40, 41, 42);

